const input = ($input.first() && $input.first().json) || {};
const entry = {
  timestamp: new Date().toISOString(),
  level: input.level || "INFO",
  workflow: input.workflow || "unknown",
  message: input.message || "",
  context: input.context || {},
};
console.log(JSON.stringify(entry));
return [{ json: entry }];
